    number: "02",
    text: "Which languages were primarily designed for systems / low-level programming?",
    helpText: null,
    options: [
      { value: "c",          label: "C" },
      { value: "ruby",       label: "Ruby" },
      { value: "cpp",        label: "C++" },
      { value: "rust",       label: "Rust" },
    ],
    correct: ["c", "cpp", "rust"],
  },
  {
    id: "q3",
    number: "03",
    text: "Which of the following languages support first-class functions?",
    helpText: null,
    options: [
      { value: "javascript", label: "JavaScript" },
      { value: "haskell",    label: "Haskell" },
      { value: "cobol",      label: "COBOL" },
      { value: "python",     label: "Python" },
    ],
    correct: ["javascript", "haskell", "python"],
  },
];

/* ── SVG helpers ───────────────────────────────────────────── */

const CheckIcon = () => `
  <svg width="12" height="12" viewBox="0 0 12 12" fill="none"
       stroke="currentColor" stroke-width="2.5" stroke-linecap="round"
       stroke-linejoin="round" aria-hidden="true">
    <polyline points="2,6 5,9 10,3"/>
  </svg>`;

const InfoIcon = () => `
  <svg width="14" height="14" viewBox="0 0 16 16" fill="none"
       stroke="currentColor" stroke-width="2" stroke-linecap="round"
       stroke-linejoin="round" aria-hidden="true">
    <circle cx="8" cy="8" r="7"/>
    <line x1="8" y1="7" x2="8" y2="11"/>
    <circle cx="8" cy="5" r="0.5" fill="currentColor" stroke="none"/>
  </svg>`;

/* ── Component functions ───────────────────────────────────── */

function CheckboxOption({ questionId, option }) {
  return `
    <label class="option-label" for="${questionId}-${option.value}">
      <input
        type="checkbox"
        id="${questionId}-${option.value}"
        name="${questionId}"
        value="${option.value}"
      />
      <span class="custom-checkbox">${CheckIcon()}</span>
      <span class="option-text">${option.label}</span>
    </label>`;
}

function HelpText({ text }) {
  if (!text) return "";
  return `
    <div class="help-text" role="note">
      ${InfoIcon()}
      <span>${text}</span>
    </div>`;
}

function QuestionField({ question }) {
  const options = question.options
    .map((opt) => CheckboxOption({ questionId: question.id, option: opt }))
    .join("");

  return `
    <div class="form-field" id="field-${question.id}" data-question="${question.id}">
      <div class="question-meta">
        <span class="question-number">Q${question.number}</span>
        <p class="question-text">${question.text}</p>
      </div>
      ${HelpText({ text: question.helpText })}
      <div class="options-list" role="group" aria-label="${question.text}">
        ${options}
      </div>
    </div>`;
}

function SubmitButton() {
  return `
    <div class="submit-row">
      <button class="btn-submit" id="submit-btn" type="submit">
        Submit answers
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none"
             stroke="currentColor" stroke-width="2.2" stroke-linecap="round"
             stroke-linejoin="round" aria-hidden="true">
          <line x1="3" y1="8" x2="13" y2="8"/>
          <polyline points="9,4 13,8 9,12"/>
        </svg>
      </button>
    </div>`;
}

function ResultBanner() {
  return `<div class="result-banner" id="result-banner" role="alert"></div>`;
}

function QuizApp({ questions }) {
  const fields = questions.map((q) => QuestionField({ question: q })).join("");
  return `
    <div class="quiz-wrapper">
      <header class="quiz-header">
        <span class="badge">Knowledge check</span>
        <h1>Computer Languages Quiz</h1>
        <p>Select all answers that apply — each question may have more than one correct choice.</p>
      </header>
      <form id="quiz-form" novalidate>
        ${fields}
        ${SubmitButton()}
        ${ResultBanner()}
      </form>
    </div>`;
}

/* ── Mount ─────────────────────────────────────────────────── */

function mount() {
  document.body.innerHTML = QuizApp({ questions: QUESTIONS });
  attachHandlers();
}

/* ── Event logic ───────────────────────────────────────────── */

function getAnswers() {
  return QUESTIONS.map((q) => {
    const checked = Array.from(
      document.querySelectorAll(`input[name="${q.id}"]:checked`)
    ).map((el) => el.value);
    return { id: q.id, checked };
  });
}

function arraysMatch(a, b) {
  return a.length === b.length && [...a].sort().join() === [...b].sort().join();
}

function showResult(score, total) {
  const banner = document.getElementById("result-banner");
  const pct = score / total;
  banner.classList.remove("success", "warning", "info");

  let cls, icon, msg;
  if (pct === 1) {
    cls = "success"; icon = "✓";
    msg = `Perfect score! You got all ${total} questions right.`;
  } else if (pct >= 0.5) {
    cls = "warning"; icon = "◎";
    msg = `Good effort — ${score} of ${total} questions correct. Review the highlighted fields.`;
  } else {
    cls = "info"; icon = "→";
    msg = `${score} of ${total} questions correct. Keep exploring!`;
  }

  banner.className = `result-banner show ${cls}`;
  banner.innerHTML = `<span>${icon}</span><span>${msg}</span>`;
  banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function attachHandlers() {
  const form = document.getElementById("quiz-form");

  form.addEventListener("submit", (e) => {
    e.preventDefault();

    const answers = getAnswers();
    let allAnswered = true;

    /* Clear previous validation states */
    document.querySelectorAll(".form-field").forEach((el) => {
      el.classList.remove("unanswered");
    });

    answers.forEach(({ id, checked }) => {
      if (checked.length === 0) {
        allAnswered = false;
        const field = document.getElementById(`field-${id}`);
        field.classList.add("unanswered");
      }
    });

    if (!allAnswered) {
      const banner = document.getElementById("result-banner");
      banner.className = "result-banner show info";
      banner.innerHTML =
        "<span>⚠</span><span>Please answer every question before submitting.</span>";
      return;
    }

    const score = answers.reduce((sum, { id, checked }) => {
      const question = QUESTIONS.find((q) => q.id === id);
      return sum + (arraysMatch(checked, question.correct) ? 1 : 0);
    }, 0);

    showResult(score, QUESTIONS.length);
  });
}

/* ── Boot ──────────────────────────────────────────────────── */
document.addEventListener("DOMContentLoaded", mount);

