  </svg>`;

const InfoIcon = () => `
  <svg width="14" height="14" viewBox="0 0 16 16" fill="none"
       stroke="currentColor" stroke-width="2" stroke-linecap="round"
       stroke-linejoin="round" aria-hidden="true">
    <circle cx="8" cy="8" r="7"/>
    <line x1="8" y1="7" x2="8" y2="11"/>
    <circle cx="8" cy="5" r="0.5" fill="currentColor" stroke="none"/>
  </svg>`;

/* ── Component functions ───────────────────────────────────── */

function CheckboxOption({ questionId, option }) {
  return `
    <label class="option-label" for="${questionId}-${option.value}">
      <input
        type="checkbox"
        id="${questionId}-${option.value}"
        name="${questionId}"
        value="${option.value}"
      />
      <span class="custom-checkbox">${CheckIcon()}</span>
      <span class="option-text">${option.label}</span>
    </label>`;
}

function HelpText({ text }) {
  if (!text) return "";
  return `
    <div class="help-text" role="note">
      ${InfoIcon()}
      <span>${text}</span>
    </div>`;
}

function QuestionField({ question }) {
  const options = question.options
    .map((opt) => CheckboxOption({ questionId: question.id, option: opt }))
    .join("");

  return `
    <div class="form-field" id="field-${question.id}" data-question="${question.id}">
      <div class="question-meta">
        <span class="question-number">Q${question.number}</span>
        <p class="question-text">${question.text}</p>
      </div>
      ${HelpText({ text: question.helpText })}
      <div class="options-list" role="group" aria-label="${question.text}">
        ${options}
      </div>
    </div>`;
}

