      <button class="btn-submit" id="submit-btn" type="submit">
        Submit answers
        <svg width="16" height="16" viewBox="0 0 16 16" fill="none"
             stroke="currentColor" stroke-width="2.2" stroke-linecap="round"
             stroke-linejoin="round" aria-hidden="true">
          <line x1="3" y1="8" x2="13" y2="8"/>
          <polyline points="9,4 13,8 9,12"/>
        </svg>
      </button>
    </div>`;
}

function ResultBanner() {
  return `<div class="result-banner" id="result-banner" role="alert"></div>`;
}

function QuizApp({ questions }) {
  const fields = questions.map((q) => QuestionField({ question: q })).join("");
  return `
    <div class="quiz-wrapper">
      <header class="quiz-header">
        <span class="badge">Knowledge check</span>
        <h1>Computer Languages Quiz</h1>
        <p>Select all answers that apply — each question may have more than one correct choice.</p>
      </header>
      <form id="quiz-form" novalidate>
        ${fields}
        ${SubmitButton()}
        ${ResultBanner()}
      </form>
    </div>`;
}

/* ── Mount ─────────────────────────────────────────────────── */

function mount() {
  document.body.innerHTML = QuizApp({ questions: QUESTIONS });
  attachHandlers();
}

/* ── Event logic ───────────────────────────────────────────── */

function getAnswers() {
  return QUESTIONS.map((q) => {
    const checked = Array.from(
      document.querySelectorAll(`input[name="${q.id}"]:checked`)
    ).map((el) => el.value);
    return { id: q.id, checked };
  });
}

function arraysMatch(a, b) {
  return a.length === b.length && [...a].sort().join() === [...b].sort().join();
}

function showResult(score, total) {
  const banner = document.getElementById("result-banner");
  const pct = score / total;
  banner.classList.remove("success", "warning", "info");

  let cls, icon, msg;
  if (pct === 1) {
    cls = "success"; icon = "✓";
    msg = `Perfect score! You got all ${total} questions right.`;
  } else if (pct >= 0.5) {
    cls = "warning"; icon = "◎";
    msg = `Good effort — ${score} of ${total} questions correct. Review the highlighted fields.`;
  } else {
    cls = "info"; icon = "→";
    msg = `${score} of ${total} questions correct. Keep exploring!`;
  }

  banner.className = `result-banner show ${cls}`;
  banner.innerHTML = `<span>${icon}</span><span>${msg}</span>`;
  banner.scrollIntoView({ behavior: "smooth", block: "nearest" });
}

function attachHandlers() {
