    document.querySelectorAll(".form-field").forEach((el) => {
      el.classList.remove("unanswered");
    });

    answers.forEach(({ id, checked }) => {
      if (checked.length === 0) {
        allAnswered = false;
        const field = document.getElementById(`field-${id}`);
        field.classList.add("unanswered");
      }
    });

    if (!allAnswered) {
      const banner = document.getElementById("result-banner");
      banner.className = "result-banner show info";
      banner.innerHTML =
        "<span>⚠</span><span>Please answer every question before submitting.</span>";
      return;
