+      return;
+    }
+
+    const score = answers.reduce((sum, { id, checked }) => {
+      const question = QUESTIONS.find((q) => q.id === id);
+      return sum + (arraysMatch(checked, question.correct) ? 1 : 0);
+    }, 0);
